const $ =                    (selector        )           => document.querySelector   (selector);
const status = $("#server-status"), diagnostics = $("#diagnostics"), objectSelect = $("#object-select")                            ;
const frameSelect = $("#frame-select")                            , fields = $("#frame-fields"), canvas = $("#sprite-canvas")                            ;
const tickOut = $("#tick-readout"), frameOut = $("#frame-readout"), timeOut = $("#time-readout"), revisionOut = $("#revision-readout"), dirtyOut = $("#dirty-readout");
const seek = $("#timeline-seek")                           , loop = $("#loop-enabled")                           , play = $("#play-toggle")                            ;
let project                          , current = 0, tick = 0, playing = false, timer                    , sheet                              ;

function object(value         )              { return value !== null && typeof value === "object" ? value                : {}; }
function array(value         )            { return Array.isArray(value) ? value : []; }
function message(value         )         { return typeof value === "string" ? value : ""; }
function normalize(payload         )               {
    const root = object(payload); const data = object(root.data); const open = object(data.document ?? data.session ?? data.project ?? data);
    const projection = object(open.projection ?? data.projection); const preview = object(open.nativePreview ?? open.preview ?? open.trace ?? data.nativePreview ?? data.preview);
    const rawFrames = array(projection.frames ?? open.frames ?? preview.frames);
    return { sessionId: message(open.sessionId ?? open.id ?? data.sessionId), name: message(open.name ?? data.name ?? "Loaded project"), revision: (open.revision ?? data.revision ?? "—")                   ,
        dirty: open.dirty === true || data.dirty === true, frames: rawFrames.map((entry, index) => ({ ...object(entry), frameId: Number(object(entry).frameId ?? object(entry).id ?? index) })),
        ranges: array(projection.spriteRanges ?? open.spriteRanges ?? data.spriteRanges).map(object), assetId: message(open.assetId ?? data.assetId) || undefined };
}
async function api(path        , init              )                       { const response = await fetch(path, { headers: { Accept: "application/json", "Content-Type": "application/json", ...(init?.headers ?? {}) }, ...init }); const body = await response.json()           ; if (!response.ok) throw new Error(message(object(body).message) || message(object(body).diagnostics) || `${response.status} ${path}`); return object(body); }
function active()                    { return project?.frames[current]; }
function update()       { const frame = active(); if (frameOut) frameOut.textContent = frame ? String(frame.frameId) : "—"; if (tickOut) tickOut.textContent = String(tick); if (timeOut) timeOut.textContent = `${tick * 33} ms`; if (seek) { seek.max = String(Math.max(0, (project?.frames.length ?? 1) - 1)); seek.value = String(current); } if (play) { play.textContent = playing ? "Pause" : "Play"; play.ariaPressed = String(playing); } draw(); }
function renderFrames()       { if (!frameSelect || !project) return; frameSelect.replaceChildren(...project.frames.map((frame, index) => { const option = document.createElement("option"); option.value = String(index); option.textContent = `#${frame.frameId} pic ${String(frame.pic ?? 0)}`; return option; })); }
function renderFields()       { if (!fields) return; const frame = active(); fields.replaceChildren(); if (!frame) return; for (const [key, value] of Object.entries(frame)) { if (key === "frameId" || typeof value !== "number") continue; const label = document.createElement("label"); label.textContent = key; const input = document.createElement("input"); input.name = key; input.type = "number"; input.value = String(value); label.append(input); fields.append(label); } }
function draw()       { const context = canvas?.getContext("2d"); const frame = active(); if (!canvas || !context) return; context.clearRect(0, 0, canvas.width, canvas.height); if (!sheet || !frame || !project) { context.fillStyle = "#b7c4bd"; context.fillText("No sprite asset available for this frame.", 20, 30); return; } const pic = Number(frame.pic ?? -1); const range = project.ranges.find((candidate) => pic >= Number(candidate.frameLo ?? candidate.frame_lo ?? 0) && pic <= Number(candidate.frameHi ?? candidate.frame_hi ?? -1)); if (!range || pic === 999) return; const w = Number(range.w), h = Number(range.h), cols = Number(range.row ?? range.col); const local = pic - Number(range.frameLo ?? range.frame_lo); const sx = (local % cols) * (w + 1), sy = Math.floor(local / cols) * (h + 1); context.imageSmoothingEnabled = false; context.drawImage(sheet, sx, sy, w, h, (canvas.width - w) / 2, (canvas.height - h) / 2, w, h); }
function selectFrame(index        )       { current = Math.max(0, Math.min(index, (project?.frames.length ?? 1) - 1)); if (frameSelect) frameSelect.value = String(current); renderFields(); update(); }
function schedule()       { if (!playing || timer !== undefined) return; timer = window.setTimeout(() => { timer = undefined; const max = Math.max(0, (project?.frames.length ?? 1) - 1); selectFrame(current >= max ? (loop?.checked ? 0 : max) : current + 1); tick++; update(); schedule(); }, 33); }
async function open(oid        )                { const response = await api("/api/project/open", { method: "POST", body: JSON.stringify({ objectId: oid }) }); project = normalize(response); if (status) status.textContent = `Loaded ${project.name} / OID ${oid}`; if (revisionOut) revisionOut.textContent = `revision ${project.revision}`; if (dirtyOut) dirtyOut.textContent = project.dirty ? "dirty" : "clean"; renderFrames(); selectFrame(0); if (project.assetId) { sheet = new Image(); sheet.src = `/api/assets/${encodeURIComponent(project.assetId)}`; sheet.onload = draw; } }
async function start()                { try { await api("/api/bootstrap"); const listing = await api("/api/project"); const items = array(object(listing).data ?? object(listing).objects); if (objectSelect) { objectSelect.replaceChildren(...items.map((item) => { const entry = object(item); const oid = Number(entry.objectId ?? entry.oid ?? entry.id); const option = document.createElement("option"); option.value = String(oid); option.textContent = `OID ${oid} ${message(entry.name)}`; if (oid === 2) option.selected = true; return option; })); } await open(objectSelect?.value === undefined || objectSelect.value === "" ? 2 : Number(objectSelect.value)); } catch (error) { if (status) status.textContent = "Project unavailable"; if (diagnostics) diagnostics.textContent = error instanceof Error ? error.message : "Unable to load project."; } }
objectSelect?.addEventListener("change", () => void open(Number(objectSelect.value))); frameSelect?.addEventListener("change", () => selectFrame(Number(frameSelect.value))); seek?.addEventListener("input", () => selectFrame(Number(seek.value)));
play?.addEventListener("click", () => { playing = !playing; update(); schedule(); }); $("#step-once")?.addEventListener("click", () => { selectFrame(current + 1); tick++; }); $("#reset-timeline")?.addEventListener("click", () => { tick = 0; selectFrame(0); });
$("#frame-editor")?.addEventListener("submit", (event) => { event.preventDefault(); const form = event.currentTarget                   ; const field = Object.entries(Object.fromEntries(new FormData(form))).find(([, value]) => value !== "")?.[0]; if (!field || !project || !active()) return; void api("/api/project/edit", { method: "POST", body: JSON.stringify({ sessionId: project.sessionId, frameId: active() .frameId, fieldId: field, value: Number(new FormData(form).get(field)), expectedRevision: project.revision }) }).then((response) => { project = normalize(response); tick = 0; selectFrame(0); }).catch((error) => { if (diagnostics) diagnostics.textContent = String(error); }); });
$("#save-project")?.addEventListener("click", () => { if (!project) return; void api("/api/project/save", { method: "POST", body: JSON.stringify({ sessionId: project.sessionId, expectedRevision: project.revision }) }).then(() => { if (diagnostics) diagnostics.textContent = "Save requested."; }).catch((error) => { if (diagnostics) diagnostics.textContent = String(error); }); });
for (const key of ["a", "d", "j", "fj", "fa", "da", "ua", "ja", "dj", "uj"]) $("#hit-" + key)?.addEventListener("click", () => { const target = Number(active()?.[`hit_${key === "fj" ? "Fj" : key === "fa" ? "Fa" : key === "da" ? "Da" : key === "ua" ? "Ua" : key === "ja" ? "ja" : key === "dj" ? "Dj" : key === "uj" ? "Uj" : key}`]); const index = project?.frames.findIndex((frame) => frame.frameId === target) ?? -1; if (index >= 0) { selectFrame(index); playing = true; schedule(); } });
void start();
